xml.Script:
        clYellow       := 'FFFF00';
        clLightBlue    := '2828FF';
        clBlue         := '0000A0';
        clBrown        := '800000';
        clLightViolett := 'FF0080';
        clRed          := 'FF0000';
        clLightGreen   := '00FF00';
        clGreen        := '008000';
        clViolett      := '800080';
        clCyan         := '00DCB4';
        clWhite        := 'FFFFFF';
        clBlack        := '222222';

        for i := 0 to 19 do
            Colors[i] := -1;

        Colors[ 0] := clCyan;
        Colors[ 5] := clLightViolett;
        Colors[10] := clBlack;
        Colors[11] := clBlue;
        Colors[12] := clLightBlue;
        Colors[13] := clLightGreen;
        Colors[14] := clGreen;
        Colors[15] := clRed;
        Colors[16] := clWhite;
        Colors[17] := clViolett;
        Colors[18] := clBrown;

        R := 0.7;
        include 'Figures\Scripts\Icosahedron_Coordinates.inc';

        D := R * 0.05;
